css:
.card{position:relative; overflow:visible}       /* 必須。hiddenで全部死ぬ */

/* 上辺に半分噛ませる（ピル） */
.tag{position:absolute; top:0; left:14px; translate:0 -50%;   /* 辺の線上に中心 */
  z-index:3; border-radius:999px; padding:4px 12px;
  font-size:11px; background:#7fc9ae; color:#fff}

/* 角から菱形で突き出す（NEW） */
.badge{position:absolute; top:-8px; left:-8px; z-index:3;
  width:30px; height:30px; background:#0b57d0;
  transform:rotate(45deg); display:grid; place-items:center}
.badge span{transform:rotate(-45deg); color:#fff; font-size:8px; font-weight:700}

/* 操作部を面の左右の縁に噛ませる */
.arrow{position:absolute; top:50%; translate:-50% -50%; z-index:3;
  width:34px; height:56px; background:#12a6bd; border-radius:4px}
.arrow--prev{left:0}
.arrow--next{left:100%}

/* 円の輪郭を分断してぶら下げる */
.clock{overflow:visible}
.pill{position:absolute; left:50%; bottom:-14px; translate:-50% 0; z-index:3;
  background:#12569e; color:#fff; border-radius:999px;
  padding:4px 14px; white-space:nowrap}
